using System;
using System.Collections.Generic;
using Framework.Grid;
using Framework.Pathfinding;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// グリッド距離マップの動作を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class GridDistanceMapTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 48;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestInitialization();
                TestBasicDistance();
                TestObstacles();
                TestDistanceQueries();
                TestPositionQueries();
                TestRecalculation();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【GridDistanceMap テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// 指定サイズのテスト用グリッドを生成する。
        /// </summary>
        /// <param name="width">グリッドの幅</param>
        /// <param name="height">グリッドの高さ</param>
        /// <returns>すべて通行可能なグリッド</returns>
        private GridMap<bool> CreateMap(
            int width = 5,
            int height = 5)
        {
            return new GridMap<bool>(
                width,
                height,
                position => true);
        }

        /// <summary>
        /// テスト用距離マップを生成する。
        /// </summary>
        /// <param name="map">計算対象のグリッド</param>
        /// <returns>未計算の距離マップ</returns>
        private GridDistanceMap<bool> CreateDistanceMap(
            GridMap<bool> map)
        {
            return new GridDistanceMap<bool>(
                map,
                position => map.GetCell(position));
        }

        /// <summary>
        /// 初期状態と引数検証を確認する。
        /// </summary>
        private void TestInitialization()
        {
            var map = CreateMap();

            var distanceMap = CreateDistanceMap(map);

            bool mapPassed =
                ReferenceEquals(distanceMap.Map, map);
            Debug.Assert(mapPassed, "グリッド参照", this);
            Check(mapPassed, "グリッド参照");

            bool calculatedPassed =
                !distanceMap.IsCalculated;
            Debug.Assert(calculatedPassed, "初期未計算状態", this);
            Check(calculatedPassed, "初期未計算状態");

            bool countPassed =
                distanceMap.ReachableCount == 0;
            Debug.Assert(countPassed, "初期到達可能セル数", this);
            Check(countPassed, "初期到達可能セル数");

            bool maxPassed =
                distanceMap.MaxDistance == -1;
            Debug.Assert(maxPassed, "初期最大距離", this);
            Check(maxPassed, "初期最大距離");

            bool distancePassed =
                distanceMap.GetDistance(Vector2Int.zero) == -1;
            Debug.Assert(distancePassed, "未計算時の距離取得", this);
            Check(distancePassed, "未計算時の距離取得");

            bool farthestPassed =
                !distanceMap.TryGetFarthestPosition(
                    out var unusedPosition,
                    out int unusedDistance) &&
                unusedPosition == default &&
                unusedDistance == -1;
            Debug.Assert(farthestPassed, "未計算時の最遠セル取得", this);
            Check(farthestPassed, "未計算時の最遠セル取得");

            bool nullMapPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new GridDistanceMap<bool>(
                        null,
                        position => true);
                });
            Debug.Assert(nullMapPassed, "nullグリッドの拒否", this);
            Check(nullMapPassed, "nullグリッドの拒否");

            bool nullPredicatePassed =
                Throws<ArgumentNullException>(() =>
                {
                    new GridDistanceMap<bool>(map, null);
                });
            Debug.Assert(nullPredicatePassed, "null判定関数の拒否", this);
            Check(nullPredicatePassed, "null判定関数の拒否");
        }

        /// <summary>
        /// 基本的な距離計算を確認する。
        /// </summary>
        private void TestBasicDistance()
        {
            var map = CreateMap();

            var distanceMap = CreateDistanceMap(map);

            Vector2Int origin = new Vector2Int(2, 2);

            bool calculatePassed =
                distanceMap.Calculate(origin) &&
                distanceMap.IsCalculated;
            Debug.Assert(calculatePassed, "距離計算の成功", this);
            Check(calculatePassed, "距離計算の成功");

            bool originPassed =
                distanceMap.Origin == origin;
            Debug.Assert(originPassed, "起点の保持", this);
            Check(originPassed, "起点の保持");

            bool zeroPassed =
                distanceMap.GetDistance(origin) == 0;
            Debug.Assert(zeroPassed, "起点の距離", this);
            Check(zeroPassed, "起点の距離");

            bool neighborPassed =
                distanceMap.GetDistance(
                    origin + Vector2Int.up) == 1 &&
                distanceMap.GetDistance(
                    origin + Vector2Int.down) == 1 &&
                distanceMap.GetDistance(
                    origin + Vector2Int.left) == 1 &&
                distanceMap.GetDistance(
                    origin + Vector2Int.right) == 1;
            Debug.Assert(neighborPassed, "上下左右の距離", this);
            Check(neighborPassed, "上下左右の距離");

            bool diagonalPassed =
                distanceMap.GetDistance(
                    new Vector2Int(3, 3)) == 2;
            Debug.Assert(diagonalPassed, "斜め位置の移動距離", this);
            Check(diagonalPassed, "斜め位置の移動距離");

            bool cornerPassed =
                distanceMap.GetDistance(
                    new Vector2Int(0, 0)) == 4 &&
                distanceMap.GetDistance(
                    new Vector2Int(4, 4)) == 4;
            Debug.Assert(cornerPassed, "グリッド端への距離", this);
            Check(cornerPassed, "グリッド端への距離");

            bool countPassed =
                distanceMap.ReachableCount == 25;
            Debug.Assert(countPassed, "全セルへの到達", this);
            Check(countPassed, "全セルへの到達");

            bool maxPassed =
                distanceMap.MaxDistance == 4;
            Debug.Assert(maxPassed, "最大距離の計算", this);
            Check(maxPassed, "最大距離の計算");
        }

        /// <summary>
        /// 障害物と到達不可能なセルを確認する。
        /// </summary>
        private void TestObstacles()
        {
            var map = CreateMap();

            // X座標2に壁を作り、Y座標4のみ通行可能とする。
            for (int y = 0; y < 4; y++)
            {
                map.SetCell(new Vector2Int(2, y), false);
            }

            var distanceMap = CreateDistanceMap(map);

            Vector2Int origin = new Vector2Int(1, 1);

            Vector2Int destination = new Vector2Int(3, 1);

            bool calculatePassed =
                distanceMap.Calculate(origin);
            Debug.Assert(calculatePassed, "障害物を含む距離計算", this);
            Check(calculatePassed, "障害物を含む距離計算");

            bool wallPassed =
                distanceMap.GetDistance(
                    new Vector2Int(2, 1)) == -1;
            Debug.Assert(wallPassed, "壁への到達拒否", this);
            Check(wallPassed, "壁への到達拒否");

            bool detourPassed =
                distanceMap.GetDistance(destination) == 8;
            Debug.Assert(detourPassed, "壁を迂回した最短距離", this);
            Check(detourPassed, "壁を迂回した最短距離");

            bool countPassed =
                distanceMap.ReachableCount == 21;
            Debug.Assert(countPassed, "壁を除く到達可能セル数", this);
            Check(countPassed, "壁を除く到達可能セル数");

            // 通路を閉鎖してグリッドを分断する。
            map.SetCell(new Vector2Int(2, 4), false);

            distanceMap.Calculate(origin);

            bool unreachablePassed =
                !distanceMap.IsReachable(destination) &&
                distanceMap.GetDistance(destination) == -1;
            Debug.Assert(unreachablePassed, "分断領域への到達拒否", this);
            Check(unreachablePassed, "分断領域への到達拒否");

            bool separatedCountPassed =
                distanceMap.ReachableCount == 10;
            Debug.Assert(separatedCountPassed, "分断後の到達可能セル数", this);
            Check(separatedCountPassed, "分断後の到達可能セル数");

            bool blockedOriginPassed =
                !distanceMap.Calculate(new Vector2Int(2, 2)) &&
                !distanceMap.IsCalculated;
            Debug.Assert(blockedOriginPassed, "通行不可能な起点の拒否", this);
            Check(blockedOriginPassed, "通行不可能な起点の拒否");

            // 起点以外をすべて通行不可能にする。
            map.Fill(false);

            map.SetCell(origin, true);

            bool isolatedPassed =
                distanceMap.Calculate(origin) &&
                distanceMap.ReachableCount == 1 &&
                distanceMap.MaxDistance == 0;
            Debug.Assert(isolatedPassed, "孤立セルからの距離計算", this);
            Check(isolatedPassed, "孤立セルからの距離計算");
        }

        /// <summary>
        /// 距離取得と範囲判定を確認する。
        /// </summary>
        private void TestDistanceQueries()
        {
            var map = CreateMap();

            var distanceMap = CreateDistanceMap(map);

            distanceMap.Calculate(Vector2Int.zero);

            bool tryPassed =
                distanceMap.TryGetDistance(
                    new Vector2Int(2, 3),
                    out int distance) &&
                distance == 5;
            Debug.Assert(tryPassed, "最短距離の安全な取得", this);
            Check(tryPassed, "最短距離の安全な取得");

            bool outsidePassed =
                !distanceMap.TryGetDistance(
                    new Vector2Int(-1, 0),
                    out int outsideDistance) &&
                outsideDistance == -1;
            Debug.Assert(outsidePassed, "範囲外セルの距離取得", this);
            Check(outsidePassed, "範囲外セルの距離取得");

            bool reachablePassed =
                distanceMap.IsReachable(new Vector2Int(4, 4));
            Debug.Assert(reachablePassed, "到達可能性の確認", this);
            Check(reachablePassed, "到達可能性の確認");

            bool withinPassed =
                distanceMap.IsWithinDistance(
                    new Vector2Int(1, 1), 3);
            Debug.Assert(withinPassed, "指定距離以内の判定", this);
            Check(withinPassed, "指定距離以内の判定");

            bool boundaryPassed =
                distanceMap.IsWithinDistance(
                    new Vector2Int(2, 1), 3);
            Debug.Assert(boundaryPassed, "距離境界の包含", this);
            Check(boundaryPassed, "距離境界の包含");

            bool beyondPassed =
                !distanceMap.IsWithinDistance(
                    new Vector2Int(2, 2), 3);
            Debug.Assert(beyondPassed, "指定距離外の判定", this);
            Check(beyondPassed, "指定距離外の判定");

            bool zeroPassed =
                distanceMap.IsWithinDistance(
                    Vector2Int.zero, 0) &&
                !distanceMap.IsWithinDistance(
                    Vector2Int.up, 0);
            Debug.Assert(zeroPassed, "距離0の範囲判定", this);
            Check(zeroPassed, "距離0の範囲判定");

            bool invalidPassed =
                !distanceMap.IsWithinDistance(
                    Vector2Int.zero, -1) &&
                !distanceMap.IsWithinDistance(
                    new Vector2Int(5, 5), 100);
            Debug.Assert(invalidPassed, "無効な範囲判定の拒否", this);
            Check(invalidPassed, "無効な範囲判定の拒否");
        }

        /// <summary>
        /// セル列挙と最遠セル取得を確認する。
        /// </summary>
        private void TestPositionQueries()
        {
            var map = CreateMap();

            var distanceMap = CreateDistanceMap(map);

            bool emptyPassed =
                CountPositions(
                    distanceMap.GetReachablePositions()) == 0;
            Debug.Assert(emptyPassed, "未計算時の空列挙", this);
            Check(emptyPassed, "未計算時の空列挙");

            distanceMap.Calculate(new Vector2Int(2, 2));

            var allPositions = new List<Vector2Int>(
                distanceMap.GetReachablePositions());

            bool allPassed =
                allPositions.Count == 25 &&
                new HashSet<Vector2Int>(
                    allPositions).Count == 25;
            Debug.Assert(allPassed, "全到達可能セルの重複なし列挙", this);
            Check(allPassed, "全到達可能セルの重複なし列挙");

            bool orderPassed =
                allPositions.Count == 25 &&
                allPositions[0] == Vector2Int.zero &&
                allPositions[1] == Vector2Int.right &&
                allPositions[5] == Vector2Int.up;
            Debug.Assert(orderPassed, "セル列挙の順序", this);
            Check(orderPassed, "セル列挙の順序");

            bool radiusOnePassed =
                CountPositions(
                    distanceMap.GetPositionsWithinDistance(1)) == 5;
            Debug.Assert(radiusOnePassed, "距離1以内のセル列挙", this);
            Check(radiusOnePassed, "距離1以内のセル列挙");

            bool radiusTwoPassed =
                CountPositions(
                    distanceMap.GetPositionsWithinDistance(2)) == 13;
            Debug.Assert(radiusTwoPassed, "距離2以内のセル列挙", this);
            Check(radiusTwoPassed, "距離2以内のセル列挙");

            bool zeroPassed =
                CountPositions(
                    distanceMap.GetPositionsWithinDistance(0)) == 1 &&
                CountPositions(
                    distanceMap.GetPositionsWithinDistance(-1)) == 0;
            Debug.Assert(zeroPassed, "距離0と負の距離の列挙", this);
            Check(zeroPassed, "距離0と負の距離の列挙");

            bool farthestPassed =
                distanceMap.TryGetFarthestPosition(
                    out Vector2Int position,
                    out int distance) &&
                distance == 4 &&
                distanceMap.GetDistance(position) == 4 &&
                position == new Vector2Int(0, 4);
            Debug.Assert(farthestPassed, "最遠セルと同距離時の選択順序", this);
            Check(farthestPassed, "最遠セルと同距離時の選択順序");

            // 列挙途中で計算結果を変更する。
            bool enumerationPassed = false;

            using (var enumerator =
                distanceMap.GetReachablePositions().GetEnumerator())
            {
                if (enumerator.MoveNext())
                {
                    distanceMap.Clear();

                    enumerationPassed =
                        Throws<InvalidOperationException>(() =>
                        {
                            enumerator.MoveNext();
                        });
                }
            }

            Debug.Assert(enumerationPassed, "列挙中の結果変更検知", this);
            Check(enumerationPassed, "列挙中の結果変更検知");
        }

        /// <summary>
        /// 再計算、初期化、安全性を確認する。
        /// </summary>
        private void TestRecalculation()
        {
            var map = CreateMap();

            var distanceMap = CreateDistanceMap(map);

            distanceMap.Calculate(Vector2Int.zero);

            bool originChangePassed =
                distanceMap.Calculate(new Vector2Int(4, 4)) &&
                distanceMap.GetDistance(Vector2Int.zero) == 8 &&
                distanceMap.GetDistance(new Vector2Int(4, 4)) == 0;
            Debug.Assert(originChangePassed, "起点変更による再計算", this);
            Check(originChangePassed, "起点変更による再計算");

            map.SetCell(new Vector2Int(3, 4), false);

            bool snapshotPassed =
                distanceMap.GetDistance(new Vector2Int(3, 4)) == 1;
            Debug.Assert(snapshotPassed, "再計算前の計算結果維持", this);
            Check(snapshotPassed, "再計算前の計算結果維持");

            bool wallChangePassed =
                distanceMap.Calculate(distanceMap.Origin) &&
                distanceMap.GetDistance(new Vector2Int(3, 4)) == -1 &&
                distanceMap.ReachableCount == 24;
            Debug.Assert(wallChangePassed, "通行条件変更後の再計算", this);
            Check(wallChangePassed, "通行条件変更後の再計算");

            bool invalidOriginPassed =
                !distanceMap.Calculate(new Vector2Int(-1, 0)) &&
                !distanceMap.IsCalculated &&
                distanceMap.ReachableCount == 0 &&
                distanceMap.MaxDistance == -1;
            Debug.Assert(invalidOriginPassed, "無効な起点と旧結果の破棄", this);
            Check(invalidOriginPassed, "無効な起点と旧結果の破棄");

            distanceMap.Calculate(Vector2Int.zero);

            distanceMap.Clear();

            bool clearPassed =
                !distanceMap.IsCalculated &&
                distanceMap.ReachableCount == 0 &&
                distanceMap.GetDistance(Vector2Int.zero) == -1;
            Debug.Assert(clearPassed, "計算結果の初期化", this);
            Check(clearPassed, "計算結果の初期化");

            var secondMap = CreateDistanceMap(map);

            distanceMap.Calculate(Vector2Int.zero);

            secondMap.Calculate(new Vector2Int(4, 4));

            bool independentPassed =
                distanceMap.GetDistance(Vector2Int.zero) == 0 &&
                secondMap.GetDistance(Vector2Int.zero) == 8;
            Debug.Assert(independentPassed, "距離マップのインスタンス独立性", this);
            Check(independentPassed, "距離マップのインスタンス独立性");

            // 通行判定中に再計算を要求する。
            GridDistanceMap<bool> recursiveMap = null;

            recursiveMap = new GridDistanceMap<bool>(
                map,
                position =>
                {
                    recursiveMap.Calculate(position);

                    return true;
                });

            bool recursivePassed =
                Throws<InvalidOperationException>(() =>
                {
                    recursiveMap.Calculate(Vector2Int.zero);
                }) &&
                !recursiveMap.IsCalculated &&
                recursiveMap.ReachableCount == 0;
            Debug.Assert(recursivePassed, "計算処理の再入防止", this);
            Check(recursivePassed, "計算処理の再入防止");

            // 通行判定で例外が発生した場合の復旧を確認する。
            bool throwException = true;

            var exceptionMap = new GridDistanceMap<bool>(
                map,
                position =>
                {
                    if (throwException &&
                        position == Vector2Int.up)
                    {
                        throw new InvalidOperationException(
                            "テスト用の例外");
                    }

                    return map.GetCell(position);
                });

            bool exceptionDetected =
                Throws<InvalidOperationException>(() =>
                {
                    exceptionMap.Calculate(Vector2Int.zero);
                });

            bool resultCleared =
                !exceptionMap.IsCalculated &&
                exceptionMap.ReachableCount == 0;

            throwException = false;

            bool recoveryPassed =
                exceptionDetected &&
                resultCleared &&
                exceptionMap.Calculate(Vector2Int.zero) &&
                exceptionMap.ReachableCount == 24;

            Debug.Assert(recoveryPassed, "計算例外後の正常復旧", this);
            Check(recoveryPassed, "計算例外後の正常復旧");
        }

        /// <summary>
        /// 列挙されたセルの件数を取得する。
        /// </summary>
        /// <param name="positions">対象のセル座標列挙</param>
        /// <returns>セルの総数</returns>
        private int CountPositions(
            IEnumerable<Vector2Int> positions)
        {
            int count = 0;

            foreach (Vector2Int position in positions)
            {
                count++;
            }

            return count;
        }

        /// <summary>
        /// 指定された型の例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();

                return false;
            }
            catch (Exception exception)
            {
                return exception.GetType() ==
                    typeof(TException);
            }
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
